-- ranking-base.sql
--
-- Base fixture for DynamicRankingBuilderTest.
-- 10 payroll periods.
--
-- P1   2026-01-01 … 2026-01-31  MONTHLY    20 employees, 10 FRA + 10 DEU.
--                                          FRA monthlyRate ascending (E10..E01):
--                                              600  700  800  900  1000 1200 1400 1600 1800 2000
--                                          DEU monthlyRate ascending (E20..E11):
--                                              500  1000 1500 2000 2500 3000 3500 4000 4500 5000
--                                          Both partitions have n=10 → percentiles fire.
--                                          Global n=20 → percentiles fire.
-- P2   2026-02-01 … 2026-02-28  MONTHLY    E01..E04 (FRA, n=4), E05..E07 (LUX, n=3).
-- P2b  2026-02-15 … 2026-02-28  BI_WEEKLY  E01, E02 (BI_WEEKLY summaries in Feb).
-- P3   2026-03-01 … 2026-03-31  MONTHLY    E01 = E02 = 5000 (R11 tie).
-- P4   2026-04-01 … 2026-04-30  MONTHLY    Range anchor for R7. No summaries.
-- P4a  2026-04-01 … 2026-04-14  BI_WEEKLY  E01 = 1400, E02 = 1200, E03 = 1000
-- P4b  2026-04-15 … 2026-04-28  BI_WEEKLY  E02 = 1200, E03 = 1000
-- P4c  2026-04-25 … 2026-04-30  BI_WEEKLY  E03 = 1000
--                                          daysCovered: E01=14, E02=28, E03=42
--                                          monthlyRate: E01=3000.00, E02=2571.43, E03=2142.86
-- P5   2099-01-01 … 2099-01-31  MONTHLY    empty (R1)
--
-- Reference currency: USD. Rates: 1 USD=1 USD, 1 USD=0.50 EUR.

DELETE FROM payroll_period_earner_percentiles;
DELETE FROM payroll_period_earner_rankings;
DELETE FROM payroll_period_aggregates;
DELETE FROM payroll_summaries;
DELETE FROM employee_periodic_assignments;
DELETE FROM payroll_periods;
DELETE FROM currency_rates;
DELETE FROM employees;
DELETE FROM roles;
DELETE FROM departments;
DELETE FROM countries;

